alter table public.teacher_post_session_tasks add column blocker text check(length(blocker)<=1000), add column recap_posted boolean not null default false;
create index teacher_post_session_owner_page on public.teacher_post_session_tasks(owner_id,ends_at,id);
create table public.teacher_home_manual (
 id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),revision integer not null default 1,
 title text not null check(length(trim(title)) between 1 and 500),student_id uuid references auth.users(id),blocker text check(length(blocker)<=1000),
 operation_key uuid,kind text not null default 'manual' check(kind in ('manual','consultation')),calendar_id text,event_id text,source_state text,starts_at timestamptz,ends_at timestamptz,
 source_updated_at timestamptz,source_checked_at timestamptz not null default now(),handled_at timestamptz,created_at timestamptz not null default now(),unique(owner_id,calendar_id,event_id,kind),unique(owner_id,operation_key)
);
create table public.teacher_home_manual_events(id bigint generated always as identity primary key,owner_id uuid not null,task_id uuid not null references teacher_home_manual(id),action text not null,detail jsonb not null,created_at timestamptz not null default now());
create table public.teacher_calendar_labels(owner_id uuid not null references teacher_post_session_settings(owner_id),calendar_id text not null,event_id text not null,kind text not null check(kind in ('session','consultation','general')),revision integer not null default 1,labelled_at timestamptz not null default now(),primary key(owner_id,calendar_id,event_id));
create table public.teacher_calendar_label_events(id bigint generated always as identity primary key,owner_id uuid not null,event_id text not null,kind text not null,revision integer not null,created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['teacher_home_manual','teacher_home_manual_events','teacher_calendar_labels','teacher_calendar_label_events'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy owner_read on public.%I for select to authenticated using(owner_id=auth.uid() and has_role(auth.uid(),''admin''))',t);end loop;end$$;
create function public.teacher_home_authorize() returns uuid language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 if auth.uid() is null or not has_role(auth.uid(),'admin') or not exists(select 1 from teacher_post_session_settings where owner_id=auth.uid()) then raise exception 'forbidden' using errcode='42501';end if;return auth.uid();end$$;
create function public.teacher_home_task_counts() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(to_jsonb(c)),'[]') from(select student_id,count(*) total,count(*) filter(where handled_at is not null) handled,count(*) filter(where handled_at is null and nullif(blocker,'') is not null) blocked from(select student_id,handled_at,blocker from teacher_post_session_tasks where owner_id=auth.uid() union all select student_id,handled_at,blocker from teacher_home_manual where owner_id=auth.uid())u where student_id is not null group by student_id)c
$$;
create function public.teacher_post_session_page(_handled boolean default false,_cursor text default null,_student_id uuid default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare o uuid:=teacher_home_authorize();c jsonb;v jsonb; n bigint;begin
 c:=case when _cursor is null then null else _cursor::jsonb end;
 select count(*) into n from teacher_post_session_tasks where owner_id=o and (handled_at is not null)=_handled and (_student_id is null or student_id=_student_id);
 select coalesce(jsonb_agg(teacher_post_session_task_json(t)||jsonb_build_object('kind','session') order by case when _handled then -extract(epoch from t.handled_at) else extract(epoch from t.ends_at) end,t.id),'[]') into v from(select * from teacher_post_session_tasks where owner_id=o and (handled_at is not null)=_handled and (_student_id is null or student_id=_student_id) and (c is null or ((case when _handled then -extract(epoch from handled_at) else extract(epoch from ends_at) end),id)>((c->>'sort')::numeric,(c->>'id')::uuid)) order by case when _handled then -extract(epoch from handled_at) else extract(epoch from ends_at) end,id limit 21)t;
 return jsonb_build_object('items',v-20,'total',n,'next_cursor',case when jsonb_array_length(v)>20 then jsonb_build_object('sort',case when _handled then -extract(epoch from (v->19->>'handled_at')::timestamptz) else extract(epoch from (v->19->>'ends_at')::timestamptz) end,'id',v->19->>'id')::text end,'student_counts',teacher_home_task_counts());end$$;
create or replace function public.teacher_post_session_home() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare o uuid:=teacher_home_authorize();s teacher_post_session_settings;begin select * into s from teacher_post_session_settings where owner_id=o;
 return jsonb_build_object('settings',jsonb_build_object('enabled',s.enabled,'activation_cutoff',s.activation_cutoff,'last_success_at',s.last_success_at,'last_attempt_at',s.last_attempt_at,'last_error',s.last_error,'catching_up',s.catching_up,'drive_root_url',case when s.drive_root_id is not null then 'https://drive.google.com/drive/folders/'||s.drive_root_id end),
 'tasks',coalesce((select jsonb_agg(teacher_post_session_task_json(t)||jsonb_build_object('kind','session') order by t.ends_at,t.id) from(select * from teacher_post_session_tasks where owner_id=o and handled_at is null order by ends_at,id limit 2)t),'[]'),
 'handled','[]'::jsonb,
 'total',(select count(*) from teacher_post_session_tasks where owner_id=o and handled_at is null),'handled_total',(select count(*) from teacher_post_session_tasks where owner_id=o and handled_at is not null),'student_counts',teacher_home_task_counts());end$$;
-- Preserve the tested checklist/matching API; add distinct posting/blocker operations.
alter function public.teacher_post_session_update(uuid,integer,text,text,boolean,text,uuid) rename to teacher_post_session_update_base;
create function public.teacher_post_session_update(_task_id uuid,_expected_revision integer,_action text,_field text default null,_value boolean default null,_doc_id text default null,_student_id uuid default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare o uuid:=teacher_home_authorize();t teacher_post_session_tasks;begin
 if _action not in ('blocker','recap_posted') then return teacher_post_session_update_base(_task_id,_expected_revision,_action,_field,_value,_doc_id,_student_id);end if;
 select * into t from teacher_post_session_tasks where id=_task_id and owner_id=o for update;if not found then raise exception 'task_not_found';end if;if t.revision<>_expected_revision then raise exception 'stale_revision' using errcode='40001';end if;
 if _action='blocker' and length(coalesce(_field,''))>1000 then raise exception 'invalid_blocker';end if;
 if _action='recap_posted' and _value is null then raise exception 'invalid_value';end if;
 update teacher_post_session_tasks set blocker=case when _action='blocker' then nullif(trim(_field),'') else blocker end,recap_posted=case when _action='recap_posted' then _value else recap_posted end,revision=revision+1 where id=t.id returning * into t;
 insert into teacher_post_session_events(task_id,owner_id,actor_id,action,detail) values(t.id,o,o,_action,jsonb_build_object('field',_field,'value',_value));return teacher_post_session_task_json(t);end$$;
create function public.teacher_home_manual_tasks(_handled boolean default false,_cursor text default null,_student_id uuid default null,_kind text default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare o uuid:=teacher_home_authorize();c jsonb;v jsonb;n bigint;begin c:=case when _cursor is null then null else _cursor::jsonb end;
 select count(*) into n from teacher_home_manual where owner_id=o and (handled_at is not null)=_handled and (_student_id is null or student_id=_student_id) and (_kind is null or kind=_kind);
 select coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object('student_name',p.display_name) order by case when _handled then -extract(epoch from t.handled_at) else extract(epoch from t.created_at) end,t.id),'[]') into v from(select * from teacher_home_manual where owner_id=o and (handled_at is not null)=_handled and (_student_id is null or student_id=_student_id) and (_kind is null or kind=_kind) and(c is null or((case when _handled then -extract(epoch from handled_at) else extract(epoch from created_at) end),id)>((c->>'sort')::numeric,(c->>'id')::uuid)) order by case when _handled then -extract(epoch from handled_at) else extract(epoch from created_at) end,id limit 21)t left join profiles p on p.class_id=t.student_id::text;
 return jsonb_build_object('items',v-20,'total',n,'next_cursor',case when jsonb_array_length(v)>20 then jsonb_build_object('sort',case when _handled then -extract(epoch from (v->19->>'handled_at')::timestamptz) else extract(epoch from (v->19->>'created_at')::timestamptz) end,'id',v->19->>'id')::text end,'student_counts',teacher_home_task_counts());end$$;
create function public.teacher_home_manual_update(_task_id uuid default null,_expected_revision integer default null,_action text default 'create',_title text default null,_student_id uuid default null,_blocker text default null,_operation_key uuid default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare o uuid:=teacher_home_authorize();t teacher_home_manual;begin
 if _student_id is not null and(not exists(select 1 from profiles where class_id=_student_id::text and archived_at is null) or has_role(_student_id,'admin')) then raise exception 'invalid_student';end if;
 if length(coalesce(_blocker,''))>1000 then raise exception 'invalid_blocker';end if;
 if _action='create' then
 if _operation_key is not null then
 perform pg_advisory_xact_lock(hashtextextended(o::text||_operation_key::text,0));select * into t from teacher_home_manual where owner_id=o and operation_key=_operation_key;
 if found then if t.title is distinct from trim(_title) or t.student_id is distinct from _student_id or t.blocker is distinct from nullif(trim(_blocker),'') then raise exception 'operation_key_conflict';end if;return to_jsonb(t)||(select jsonb_build_object('student_name',p.display_name) from(select 1)seed left join profiles p on p.class_id=t.student_id::text);end if;end if;
 insert into teacher_home_manual(owner_id,title,student_id,blocker,operation_key) values(o,trim(_title),_student_id,nullif(trim(_blocker),''),_operation_key) returning * into t;
 else select * into t from teacher_home_manual where id=_task_id and owner_id=o for update;if not found then raise exception 'task_not_found';end if;if t.revision is distinct from _expected_revision then raise exception 'stale_revision' using errcode='40001';end if;
 if _action='handle' then t.handled_at=now();elsif _action='reopen' then t.handled_at=null;elsif _action='edit' then t.title=trim(_title);t.student_id=_student_id;t.blocker=nullif(trim(_blocker),'');else raise exception 'invalid_action';end if;
 update teacher_home_manual set title=t.title,student_id=t.student_id,blocker=t.blocker,handled_at=t.handled_at,revision=revision+1 where id=t.id returning * into t;end if;
 insert into teacher_home_manual_events(owner_id,task_id,action,detail) values(o,t.id,_action,to_jsonb(t));return to_jsonb(t)||(select jsonb_build_object('student_name',p.display_name) from(select 1)seed left join profiles p on p.class_id=t.student_id::text);end$$;
create function public.teacher_home_label(_event_id text,_kind text,_expected_revision integer default 0) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare o uuid:=teacher_home_authorize();c text;l teacher_calendar_labels;begin
 if _kind not in('session','consultation','general') or length(_event_id) not between 1 and 1024 then raise exception 'invalid_label';end if;
 select calendar_id into c from teacher_post_session_settings where owner_id=o;perform pg_advisory_xact_lock(hashtextextended(o::text||_event_id,0));select * into l from teacher_calendar_labels where owner_id=o and calendar_id=c and event_id=_event_id;
 if l.kind is distinct from _kind and (exists(select 1 from teacher_post_session_tasks where owner_id=o and calendar_id=c and event_id=_event_id) or exists(select 1 from teacher_home_manual where owner_id=o and calendar_id=c and event_id=_event_id and kind='consultation')) then raise exception 'event_has_task_cannot_relabel';end if;
 if coalesce(l.revision,0)<>_expected_revision then raise exception 'stale_revision' using errcode='40001';end if;
 insert into teacher_calendar_labels(owner_id,calendar_id,event_id,kind) values(o,c,_event_id,_kind) on conflict(owner_id,calendar_id,event_id) do update set kind=excluded.kind,labelled_at=now(),revision=teacher_calendar_labels.revision+1 returning * into l;
 insert into teacher_calendar_label_events(owner_id,event_id,kind,revision) values(o,_event_id,_kind,l.revision);return to_jsonb(l);end$$;
create function public.teacher_home_consultation_source(_owner uuid,_lease uuid,_event text,_source jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare s teacher_post_session_settings;l teacher_calendar_labels;t teacher_home_manual;begin
 select * into s from teacher_post_session_settings where owner_id=_owner and lease_token=_lease and lease_until>now() and enabled and has_role(_owner,'admin') for update;if not found then raise exception 'lease_lost';end if;
 select * into l from teacher_calendar_labels where owner_id=_owner and calendar_id=s.calendar_id and event_id=_event and kind='consultation';if not found then return;end if;
 select * into t from teacher_home_manual where owner_id=_owner and calendar_id=s.calendar_id and event_id=_event and kind='consultation' for update;
 if t.id is null then
 if _source->>'source_state'<>'ended' or not coalesce((_source->>'eligible_guest')::boolean,false) or (_source->>'ends_at')::timestamptz<greatest(s.activation_cutoff,l.labelled_at) or (_source->>'ends_at')::timestamptz>now() then return;end if;
 insert into teacher_home_manual(owner_id,title,kind,calendar_id,event_id,source_state,starts_at,ends_at,source_updated_at) values(_owner,'Follow up: '||left(_source->>'source_title',450),'consultation',s.calendar_id,_event,'ended',(_source->>'starts_at')::timestamptz,(_source->>'ends_at')::timestamptz,(_source->>'source_updated_at')::timestamptz);
 else
 if _source->>'source_state'<>'unavailable' and (_source->>'source_updated_at')::timestamptz<t.source_updated_at then update teacher_home_manual set source_checked_at=now() where id=t.id;return;end if;
 if t.source_state is distinct from _source->>'source_state' or (_source ? 'ends_at' and t.ends_at is distinct from (_source->>'ends_at')::timestamptz) then insert into teacher_home_manual_events(owner_id,task_id,action,detail) values(_owner,t.id,'source_changed',_source);end if;
 update teacher_home_manual set source_checked_at=now(),source_updated_at=case when _source->>'source_state'='unavailable' then source_updated_at else (_source->>'source_updated_at')::timestamptz end,source_state=_source->>'source_state',starts_at=coalesce((_source->>'starts_at')::timestamptz,starts_at),ends_at=coalesce((_source->>'ends_at')::timestamptz,ends_at) where id=t.id;end if;end$$;
create function public.teacher_home_payments(_cursor text default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare o uuid:=teacher_home_authorize();c jsonb;v jsonb;r jsonb;n bigint;begin c:=case when _cursor is null then null else _cursor::jsonb end;
 select coalesce(jsonb_agg(to_jsonb(p) order by paid_at desc,id desc),'[]') into r from(select id,paid_at,status,product,currency,amount_cents,amount_refunded_cents,student_id,payer_name,email,match_state,grant_state,granted_credits,source,offer_id,livemode,false grantable,false review_required from stripe_payments where livemode and paid_at>=now()-interval '90 days' order by paid_at desc,id desc limit 3)p;
 select count(*) into n from stripe_payments where livemode and grant_state not in('granted','dismissed') and match_state<>'ignored' and status='succeeded' and amount_refunded_cents=0 and(grant_state='awaiting' or(match_state='unmatched' and source='webhook'));
 select coalesce(jsonb_agg(to_jsonb(p) order by paid_at desc,id desc),'[]') into v from(select id,paid_at,status,product,currency,amount_cents,amount_refunded_cents,student_id,payer_name,email,match_state,grant_state,granted_credits,source,offer_id,livemode,false grantable,true review_required from stripe_payments where livemode and grant_state not in('granted','dismissed') and match_state<>'ignored' and status='succeeded' and amount_refunded_cents=0 and(grant_state='awaiting' or(match_state='unmatched' and source='webhook')) and(c is null or(paid_at,id)<((c->>'at')::timestamptz,(c->>'id')::uuid)) order by paid_at desc,id desc limit 4)p;
 return jsonb_build_object('recent',r,'attention',v-3,'attention_count',n,'next_cursor',case when jsonb_array_length(v)>3 then jsonb_build_object('at',v->2->>'paid_at','id',v->2->>'id')::text end);end$$;
create function public.teacher_home_results() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare o uuid:=teacher_home_authorize();v jsonb;begin
 select coalesce(jsonb_agg(to_jsonb(r) order by completed_at desc,id desc),'[]') into v from(select h.id,h.class_id student_id,p.display_name student_name,h.pt,h.section,h.mode,h.initial_score,h.initial_total,case when h.br_used then h.br_score end br_score,h.completed_at from section_history h join profiles p on p.class_id=h.class_id and p.archived_at is null join auth.users u on u.id::text=p.class_id where not has_role(u.id,'admin') and h.completed_at is not null order by h.completed_at desc,h.id desc limit 3)r;return v;end$$;
do $$declare f record;begin for f in select p.oid::regprocedure sig,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'teacher_home_%' or p.proname in('teacher_post_session_home','teacher_post_session_page','teacher_post_session_update','teacher_post_session_update_base'))loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);if f.proname in('teacher_home_manual_tasks','teacher_home_manual_update','teacher_home_payments','teacher_home_results','teacher_home_label','teacher_post_session_home','teacher_post_session_page','teacher_post_session_update') then execute format('grant execute on function %s to authenticated',f.sig);end if;end loop;end$$;
grant usage,select on sequence teacher_home_manual_events_id_seq,teacher_calendar_label_events_id_seq to service_role;
-- Selected fields only; never export auth data to clients. Cached at most 60 seconds by the owner-only edge reader.
create function public.teacher_home_roster(_owner uuid) returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'email',u.email,'name',p.display_name,'archived',p.archived_at is not null,'admin',has_role(u.id,'admin'),'aliases',coalesce(to_jsonb(f.aliases),'[]'))),'[]') from auth.users u join profiles p on p.class_id=u.id::text left join teacher_student_folders f on f.owner_id=_owner and f.student_id=u.id where exists(select 1 from teacher_post_session_settings where owner_id=_owner) and has_role(_owner,'admin')
$$;
revoke all on function public.teacher_home_roster(uuid) from public,anon,authenticated;
grant execute on function public.teacher_home_roster(uuid) to service_role;